using CTXD.Server.Data;using Npgsql;
namespace CTXD.Server.Services;
public sealed record KfzbSeasonProvision(int SeasonNo,DateTimeOffset SignupOpensAt,DateTimeOffset QualifierOpensAt,DateTimeOffset Phase2OpensAt,DateTimeOffset EndsAt,int MinLevel,int SupportLevel);
public sealed record KfzbMatchProvision(int Phase,int Layer,int Round,int LegacyMatchId,long Player1Id,long Player2Id,DateTimeOffset StartsAt,DateTimeOffset DeadlineAt);
public sealed record KfzbSyncRequest(int[] GeneralIds);
public sealed record KfzbMatchView(long Id,int Phase,int Layer,int Round,int LegacyMatchId,long OpponentPlayerId,long? BattleId,int State,long? WinnerPlayerId,DateTimeOffset StartsAt,DateTimeOffset DeadlineAt);
public sealed record KfzbView(long SeasonId,int SeasonNo,int GlobalState,DateTimeOffset NextStateAt,int MinLevel,int SupportLevel,bool Eligible,bool Signed,bool Synced,bool Eliminated,long? CompetitorId,int Wins,int Losses,KfzbMatchView? Match);
public sealed record KfzbTableEntry(long MatchId,int Phase,int Layer,int Round,int LegacyMatchId,long Player1Id,string Player1,long Player2Id,string Player2,int State,long? WinnerPlayerId,long? BattleId);
public sealed record KfzbSupportRequest(long MatchId,long CompetitorId);
public sealed record KfzbSupportResult(long MatchId,long CompetitorId,int PotentialTicket,int Flower1,int Flower2);
public sealed record KfzbSupportClaimResult(int Cards,int FreeCards);
public sealed record KfzbFeastCardView(int FreeCards,int GoldCards,int CardsBought,int GoldCard1,int GoldCard10,int DrinkNum,int GoldDrink);
public sealed record KfzbFeastCardBuyRequest(int Type);
public sealed record KfzbFeastCardBuyResult(int Cards,int GoldSpent,int FreeCards,int GoldCards,int CardsBought);
public sealed class KfzbService(GameDb db,GamePushHub push,BattleService battles,DstqActivityService dstq)
{
 public async Task<long> ProvisionSeasonAsync(KfzbSeasonProvision x,CancellationToken ct){if(x.SignupOpensAt>=x.QualifierOpensAt||x.QualifierOpensAt>=x.Phase2OpensAt||x.Phase2OpensAt>=x.EndsAt||x.MinLevel<1||x.SupportLevel<1)throw new GameException("KFZB_SCHEDULE_INVALID","KFZB schedule is invalid.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var q=new NpgsqlCommand("INSERT INTO kfzb_seasons(season_no,signup_opens_at,qualifier_opens_at,phase2_opens_at,ends_at,min_level,support_level) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(season_no) DO UPDATE SET signup_opens_at=$2,qualifier_opens_at=$3,phase2_opens_at=$4,ends_at=$5,min_level=$6,support_level=$7,updated_at=now() RETURNING id",c);q.Parameters.AddWithValue(x.SeasonNo);q.Parameters.AddWithValue(x.SignupOpensAt);q.Parameters.AddWithValue(x.QualifierOpensAt);q.Parameters.AddWithValue(x.Phase2OpensAt);q.Parameters.AddWithValue(x.EndsAt);q.Parameters.AddWithValue(x.MinLevel);q.Parameters.AddWithValue(x.SupportLevel);return Convert.ToInt64(await q.ExecuteScalarAsync(ct));}
 public async Task<KfzbView> SignupAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season;int state,level,min;await using(var q=new NpgsqlCommand("SELECT s.id,s.global_state,p.level,s.min_level FROM kfzb_seasons s JOIN players p ON p.id=$1 WHERE s.ends_at>now() ORDER BY season_no DESC LIMIT 1 FOR UPDATE OF s",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_INACTIVE","No KFZB season is active.",409);season=r.GetInt64(0);state=r.GetInt16(1);level=r.GetInt32(2);min=r.GetInt32(3);}if(state!=20)throw new GameException("KFZB_SIGNUP_CLOSED","KFZB signup is only allowed in state 20.",409);if(level<min)throw new GameException("KFZB_LEVEL_LOW","Player level is below the legacy KFZB minimum.",403);var generals=new List<int>();await using(var q=new NpgsqlCommand("SELECT general_id FROM player_generals WHERE player_id=$1 AND general_type=2 ORDER BY general_id",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))generals.Add(r.GetInt32(0));}if(generals.Count==0)throw new GameException("KFZB_GENERALS_REQUIRED","KFZB signup requires military generals.");await using(var q=new NpgsqlCommand("INSERT INTO kfzb_signups(season_id,player_id,general_ids) VALUES($1,$2,$3)",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(generals.ToArray());try{await q.ExecuteNonQueryAsync(ct);}catch(PostgresException e)when(e.SqlState==PostgresErrorCodes.UniqueViolation){throw new GameException("KFZB_ALREADY_SIGNED","Player already signed up.",409);}}await using(var r=new NpgsqlCommand("INSERT INTO kfzb_rewards(season_id,player_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){r.Parameters.AddWithValue(season);r.Parameters.AddWithValue(player);await r.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);await push.BroadcastAsync("kfzb.state",new{seasonId=season,state=30,reason="signup"},ct);return await GetAsync(player,ct);}
 public async Task<KfzbView> SyncAsync(long player,int[] ids,CancellationToken ct){ids=ids.Distinct().ToArray();if(ids.Length==0)throw new GameException("KFZB_GENERALS_REQUIRED","Select at least one general.");await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season;bool dead;await using(var q=new NpgsqlCommand("SELECT s.id,g.eliminated FROM kfzb_seasons s JOIN kfzb_signups g ON g.season_id=s.id AND g.player_id=$1 WHERE s.global_state<=70 ORDER BY s.season_no DESC LIMIT 1 FOR UPDATE OF g",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_NOT_SIGNED","KFZB signup is required.",409);season=r.GetInt64(0);dead=r.GetBoolean(1);}if(dead)throw new GameException("KFZB_ELIMINATED","Eliminated players cannot synchronize formation.",409);await using(var q=new NpgsqlCommand("SELECT count(*) FROM player_generals WHERE player_id=$1 AND general_type=2 AND general_id=ANY($2)",c,t)){q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(ids);if(Convert.ToInt32(await q.ExecuteScalarAsync(ct))!=ids.Length)throw new GameException("KFZB_GENERAL_INVALID","A general is duplicated or not owned.",403);}await using(var q=new NpgsqlCommand("UPDATE kfzb_signups SET general_ids=$3,synced_at=now() WHERE season_id=$1 AND player_id=$2",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(ids);await q.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);await push.SendAsync(player,"kfzb.updated",new{reason="synced",season},ct);return await GetAsync(player,ct);}
 public async Task<long> ProvisionMatchAsync(KfzbMatchProvision x,CancellationToken ct){if(x.Phase is not(1 or 2)||x.Player1Id==x.Player2Id||x.StartsAt>=x.DeadlineAt)throw new GameException("KFZB_MATCH_INVALID","KFZB match topology is invalid.");await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season;int state;int[] a,b;await using(var q=new NpgsqlCommand("SELECT id,global_state FROM kfzb_seasons WHERE ends_at>now() ORDER BY season_no DESC LIMIT 1 FOR UPDATE",c,t)){await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_INACTIVE","No active season.");season=r.GetInt64(0);state=r.GetInt16(1);}if((x.Phase==1&&state is <30 or >=51)||(x.Phase==2&&state is <51 or >70))throw new GameException("KFZB_PHASE_INVALID","Match phase is not active.",409);async Task<int[]> G(long p){await using var q=new NpgsqlCommand("SELECT general_ids FROM kfzb_signups WHERE season_id=$1 AND player_id=$2 AND eliminated=false",c,t);q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(p);return await q.ExecuteScalarAsync(ct)as int[]??throw new GameException("KFZB_PLAYER_INELIGIBLE","Both players must be active competitors.",409);}a=await G(x.Player1Id);b=await G(x.Player2Id);int af,df,city;await using(var q=new NpgsqlCommand("SELECT p.force_id,g.location_id FROM players p JOIN player_generals g ON g.player_id=p.id AND g.general_id=$2 WHERE p.id=$1",c,t)){q.Parameters.AddWithValue(x.Player1Id);q.Parameters.AddWithValue(a[0]);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);af=r.GetInt16(0);city=r.GetInt32(1);}await using(var q=new NpgsqlCommand("SELECT force_id FROM players WHERE id=$1",c,t)){q.Parameters.AddWithValue(x.Player2Id);df=Convert.ToInt16(await q.ExecuteScalarAsync(ct));}long battle;await using(var q=new NpgsqlCommand("INSERT INTO world_battle_handoffs(city_id,attacker_player_id,attacker_general_id,attacker_force_id,defender_force_id,battle_type,result_payload) VALUES($1,$2,$3,$4,$5,17,jsonb_build_object('defenderPlayerId',$6,'defenderGeneralId',$7,'attackerGenerals',to_jsonb($8::integer[]),'defenderGenerals',to_jsonb($9::integer[]),'kfzbSeasonId',$10,'kfzbPhase',$11,'kfzbLayer',$12,'kfzbRound',$13)) RETURNING id",c,t)){q.Parameters.AddWithValue(city);q.Parameters.AddWithValue(x.Player1Id);q.Parameters.AddWithValue(a[0]);q.Parameters.AddWithValue(af);q.Parameters.AddWithValue(df);q.Parameters.AddWithValue(x.Player2Id);q.Parameters.AddWithValue(b[0]);q.Parameters.AddWithValue(a);q.Parameters.AddWithValue(b);q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(x.Phase);q.Parameters.AddWithValue(x.Layer);q.Parameters.AddWithValue(x.Round);battle=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}long match;await using(var q=new NpgsqlCommand("INSERT INTO kfzb_matches(season_id,phase,layer_no,round_no,legacy_match_id,player1_id,player2_id,battle_id,state,starts_at,deadline_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8,1,$9,$10) RETURNING id",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(x.Phase);q.Parameters.AddWithValue(x.Layer);q.Parameters.AddWithValue(x.Round);q.Parameters.AddWithValue(x.LegacyMatchId);q.Parameters.AddWithValue(x.Player1Id);q.Parameters.AddWithValue(x.Player2Id);q.Parameters.AddWithValue(battle);q.Parameters.AddWithValue(x.StartsAt);q.Parameters.AddWithValue(x.DeadlineAt);match=Convert.ToInt64(await q.ExecuteScalarAsync(ct));}await t.CommitAsync(ct);await push.SendAsync(x.Player1Id,"kfzb.match",new{matchId=match,battleId=battle,x.Phase,x.Layer,x.Round,opponent=x.Player2Id},ct);await push.SendAsync(x.Player2Id,"kfzb.match",new{matchId=match,battleId=battle,x.Phase,x.Layer,x.Round,opponent=x.Player1Id},ct);return match;}
 public async Task<KfzbView> GetAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await SettleAsync(c,ct);return await ReadAsync(c,player,ct);}
 public async Task<KfzbTableEntry[]> TableAsync(long player,CancellationToken ct){await GetAsync(player,ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var q=new NpgsqlCommand("SELECT m.id,m.phase,m.layer_no,m.round_no,m.legacy_match_id,m.player1_id,p1.name,m.player2_id,p2.name,m.state,m.winner_player_id,m.battle_id FROM kfzb_matches m JOIN players p1 ON p1.id=m.player1_id JOIN players p2 ON p2.id=m.player2_id WHERE m.season_id=(SELECT season_id FROM kfzb_signups WHERE player_id=$1 ORDER BY season_id DESC LIMIT 1) ORDER BY m.phase,m.layer_no DESC,m.legacy_match_id,m.round_no",c);q.Parameters.AddWithValue(player);var list=new List<KfzbTableEntry>();await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetInt64(0),r.GetInt16(1),r.GetInt32(2),r.GetInt32(3),r.GetInt32(4),r.GetInt64(5),r.GetString(6),r.GetInt64(7),r.GetString(8),r.GetInt16(9),r.IsDBNull(10)?null:r.GetInt64(10),r.IsDBNull(11)?null:r.GetInt64(11)));return list.ToArray();}
 public Task<KfzbCoreRewardView> RewardAsync(long player,CancellationToken ct)=>KfzbRewardLifecycle.GetAsync(db,player,ct);
 public Task<KfzbCoreRewardClaimResult> ClaimRewardAsync(long player,CancellationToken ct)=>KfzbRewardLifecycle.ClaimAsync(db,push,player,ct);
 public async Task TickAsync(CancellationToken ct){await using(var c=await db.DataSource.OpenConnectionAsync(ct)){await using var q=new NpgsqlCommand("UPDATE kfzb_seasons SET global_state=CASE WHEN now()<signup_opens_at THEN 10 WHEN now()<qualifier_opens_at THEN 20 WHEN now()<phase2_opens_at THEN 30 WHEN now()<ends_at THEN 51 ELSE 70 END,updated_at=now() WHERE global_state<>CASE WHEN now()<signup_opens_at THEN 10 WHEN now()<qualifier_opens_at THEN 20 WHEN now()<phase2_opens_at THEN 30 WHEN now()<ends_at THEN 51 ELSE 70 END",c);if(await q.ExecuteNonQueryAsync(ct)>0)await push.BroadcastAsync("kfzb.state",new{reason="phase"},ct);}var due=new List<(long battle,long player)>();await using(var c=await db.DataSource.OpenConnectionAsync(ct)){await using var q=new NpgsqlCommand("SELECT battle_id,player1_id FROM kfzb_matches WHERE state=1 AND deadline_at<=now()",c);await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))due.Add((r.GetInt64(0),r.GetInt64(1)));}foreach(var x in due)for(var i=0;i<512;i++){var result=await battles.AdvanceAsync(x.player,x.battle,ct);if(result.Status!=0)break;}}
 public async Task<KfzbSupportResult> SupportAsync(long player,KfzbSupportRequest x,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);long season,p1,p2,c1,c2;int state,supportLevel,playerLevel,legacyMatch,round,matchState;DateTimeOffset starts;await using(var q=new NpgsqlCommand("SELECT m.season_id,s.global_state,s.support_level,p.level,m.player1_id,m.player2_id,g1.competitor_id,g2.competitor_id,m.legacy_match_id,m.round_no,m.state,m.starts_at FROM kfzb_matches m JOIN kfzb_seasons s ON s.id=m.season_id JOIN players p ON p.id=$2 JOIN kfzb_signups g1 ON g1.season_id=m.season_id AND g1.player_id=m.player1_id JOIN kfzb_signups g2 ON g2.season_id=m.season_id AND g2.player_id=m.player2_id WHERE m.id=$1 FOR UPDATE OF m",c,t)){q.Parameters.AddWithValue(x.MatchId);q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_MATCH_NOT_FOUND","KFZB match does not exist.",404);season=r.GetInt64(0);state=r.GetInt16(1);supportLevel=r.GetInt32(2);playerLevel=r.GetInt32(3);p1=r.GetInt64(4);p2=r.GetInt64(5);c1=r.GetInt64(6);c2=r.GetInt64(7);legacyMatch=r.GetInt32(8);round=r.GetInt32(9);matchState=r.GetInt16(10);starts=r.GetFieldValue<DateTimeOffset>(11);}if(state<51||state>70||matchState!=1)throw new GameException("KFZB_SUPPORT_CLOSED","This match cannot receive support.",409);if(playerLevel<supportLevel)throw new GameException("KFZB_SUPPORT_LEVEL_LOW","Player level is below the legacy support minimum.",403);if(x.CompetitorId!=c1&&x.CompetitorId!=c2)throw new GameException("KFZB_SUPPORT_TARGET_INVALID","Target is not in this match.");await using(var alive=new NpgsqlCommand("SELECT 1 FROM kfzb_signups WHERE season_id=$1 AND player_id=$2 AND eliminated=false",c,t)){alive.Parameters.AddWithValue(season);alive.Parameters.AddWithValue(player);if(await alive.ExecuteScalarAsync(ct)is not null)throw new GameException("KFZB_COMPETITOR_CANNOT_SUPPORT","A surviving competitor cannot support.",403);}await using(var init=new NpgsqlCommand("INSERT INTO kfzb_spectator_state(season_id,player_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){init.Parameters.AddWithValue(season);init.Parameters.AddWithValue(player);await init.ExecuteNonQueryAsync(ct);}var roundKey=legacyMatch>3?0:round;var ticket=DateTimeOffset.UtcNow<starts?400:200;var flowerColumn=legacyMatch>3?"flower1":"flower2";int f1,f2;await using(var use=new NpgsqlCommand($"UPDATE kfzb_spectator_state SET {flowerColumn}={flowerColumn}-1,updated_at=now() WHERE season_id=$1 AND player_id=$2 AND {flowerColumn}>0 RETURNING flower1,flower2",c,t)){use.Parameters.AddWithValue(season);use.Parameters.AddWithValue(player);await using var r=await use.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_NO_FLOWER","No legacy support flower remains.",409);f1=r.GetInt32(0);f2=r.GetInt32(1);}await using(var add=new NpgsqlCommand("INSERT INTO kfzb_supports(season_id,player_id,match_id,round_key,target_competitor_id,potential_ticket) VALUES($1,$2,$3,$4,$5,$6)",c,t)){add.Parameters.AddWithValue(season);add.Parameters.AddWithValue(player);add.Parameters.AddWithValue(x.MatchId);add.Parameters.AddWithValue(roundKey);add.Parameters.AddWithValue(x.CompetitorId);add.Parameters.AddWithValue(ticket);try{await add.ExecuteNonQueryAsync(ct);}catch(PostgresException e)when(e.SqlState==PostgresErrorCodes.UniqueViolation){throw new GameException("KFZB_ALREADY_SUPPORTED","This match round was already supported.",409);}}await t.CommitAsync(ct);await push.SendAsync(p1,"kfzb.support",new{x.MatchId,x.CompetitorId},ct);await push.SendAsync(p2,"kfzb.support",new{x.MatchId,x.CompetitorId},ct);return new(x.MatchId,x.CompetitorId,ticket,f1,f2);}
 public async Task<KfzbSupportClaimResult> ClaimSupportAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await SettleAsync(c,ct);await using var t=await c.BeginTransactionAsync(ct);long season;await using(var q=new NpgsqlCommand("SELECT id FROM kfzb_seasons ORDER BY season_no DESC LIMIT 1",c,t)){season=Convert.ToInt64(await q.ExecuteScalarAsync(ct)??throw new GameException("KFZB_INACTIVE","No KFZB season is available.",404));}int cards;await using(var q=new NpgsqlCommand("WITH won AS (UPDATE kfzb_supports SET taken=true WHERE season_id=$1 AND player_id=$2 AND rewarded=1 AND taken=false RETURNING 1) SELECT count(*)::int FROM won",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);cards=Convert.ToInt32(await q.ExecuteScalarAsync(ct));}if(cards<=0)throw new GameException("KFZB_NO_SUPPORT_REWARD","No winning support card is available.",409);int free;await using(var q=new NpgsqlCommand("INSERT INTO kfzb_spectator_state(season_id,player_id,free_feast_cards) VALUES($1,$2,10+$3) ON CONFLICT(season_id,player_id) DO UPDATE SET free_feast_cards=kfzb_spectator_state.free_feast_cards+$3,updated_at=now() RETURNING free_feast_cards",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(cards);free=Convert.ToInt32(await q.ExecuteScalarAsync(ct));}await t.CommitAsync(ct);await push.SendAsync(player,"kfzb.feast",new{reason="supportClaim",cards,freeCards=free},ct);return new(cards,free);}
 public async Task<KfzbFeastCardView> FeastCardsAsync(long player,CancellationToken ct){await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var season=await FeastSeasonAsync(c,t,ct);await using(var q=new NpgsqlCommand("INSERT INTO kfzb_spectator_state(season_id,player_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);await q.ExecuteNonQueryAsync(ct);}await using var read=new NpgsqlCommand("SELECT free_feast_cards,gold_feast_cards,feast_cards_bought,drink_num FROM kfzb_spectator_state WHERE season_id=$1 AND player_id=$2",c,t);read.Parameters.AddWithValue(season);read.Parameters.AddWithValue(player);await using var r=await read.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var free=r.GetInt32(0);var gold=r.GetInt32(1);var bought=r.GetInt32(2);var drink=r.GetInt32(3);await r.CloseAsync();await t.CommitAsync(ct);return new(free,gold,bought,FeastGold(bought,1),FeastGold(bought,10),drink,500);}
 public async Task<KfzbFeastCardBuyResult> BuyFeastCardsAsync(long player,int type,CancellationToken ct){var cards=type switch{1=>1,2=>10,_=>throw new GameException("KFZB_FEAST_CARD_TYPE_INVALID","Legacy Feast card type must be 1 or 2.")};await TickAsync(ct);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var season=await FeastSeasonAsync(c,t,ct);await using(var init=new NpgsqlCommand("INSERT INTO kfzb_spectator_state(season_id,player_id) VALUES($1,$2) ON CONFLICT DO NOTHING",c,t)){init.Parameters.AddWithValue(season);init.Parameters.AddWithValue(player);await init.ExecuteNonQueryAsync(ct);}int bought;await using(var q=new NpgsqlCommand("SELECT feast_cards_bought FROM kfzb_spectator_state WHERE season_id=$1 AND player_id=$2 FOR UPDATE",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);bought=Convert.ToInt32(await q.ExecuteScalarAsync(ct));}var cost=FeastGold(bought,cards);await using(var pay=new NpgsqlCommand("UPDATE players SET sys_gold=sys_gold-LEAST(sys_gold,$2),user_gold=user_gold-GREATEST(0,$2-sys_gold),updated_at=now() WHERE id=$1 AND sys_gold+user_gold >= $2",c,t)){pay.Parameters.AddWithValue(player);pay.Parameters.AddWithValue(cost);if(await pay.ExecuteNonQueryAsync(ct)!=1)throw new GameException("KFZB_FEAST_GOLD_NOT_ENOUGH","Not enough gold for Feast cards.");}int free,gold,total;await using(var q=new NpgsqlCommand("UPDATE kfzb_spectator_state SET gold_feast_cards=gold_feast_cards+$3,feast_cards_bought=feast_cards_bought+$3,updated_at=now() WHERE season_id=$1 AND player_id=$2 RETURNING free_feast_cards,gold_feast_cards,feast_cards_bought",c,t)){q.Parameters.AddWithValue(season);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(cards);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);free=r.GetInt32(0);gold=r.GetInt32(1);total=r.GetInt32(2);}await dstq.RecordGoldSpendAsync(c,t,player,cost,ct);await t.CommitAsync(ct);await push.SendAsync(player,"kfzb.feast",new{reason="cardsBought",cards,goldSpent=cost},ct);return new(cards,cost,free,gold,total);}
 static int FeastGold(int bought,int cards)=>cards*(20+bought*2)+cards*(cards-1);
 static async Task<long> FeastSeasonAsync(NpgsqlConnection c,NpgsqlTransaction t,CancellationToken ct){await using var q=new NpgsqlCommand("SELECT id,COALESCE(feast_opens_at,date_trunc('day',ends_at)+interval '1 day'),COALESCE(feast_ends_at,date_trunc('day',ends_at)+interval '2 days') FROM kfzb_seasons ORDER BY season_no DESC LIMIT 1",c,t);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_INACTIVE","No KFZB season is available.",404);var id=r.GetInt64(0);var now=DateTimeOffset.UtcNow;if(now<r.GetFieldValue<DateTimeOffset>(1)||now>=r.GetFieldValue<DateTimeOffset>(2))throw new GameException("KFZB_FEAST_CLOSED","KFZB Feast is not open.",409);return id;}
 async Task SettleAsync(NpgsqlConnection c,CancellationToken ct){await using var t=await c.BeginTransactionAsync(ct);var done=new List<(long id,long season,int phase,int layer,long p1,long p2,long winner)>();await using(var q=new NpgsqlCommand("SELECT m.id,m.season_id,m.phase,m.layer_no,m.player1_id,m.player2_id,CASE b.winner_side WHEN 1 THEN m.player1_id ELSE m.player2_id END FROM kfzb_matches m JOIN battles b ON b.id=m.battle_id WHERE m.state=1 AND b.status<>0 FOR UPDATE OF m",c,t)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))done.Add((r.GetInt64(0),r.GetInt64(1),r.GetInt16(2),r.GetInt32(3),r.GetInt64(4),r.GetInt64(5),r.GetInt64(6)));}foreach(var x in done){await using var ledger=new NpgsqlCommand("INSERT INTO kfzb_settlement_ledger(match_id) VALUES($1) ON CONFLICT DO NOTHING",c,t);ledger.Parameters.AddWithValue(x.id);if(await ledger.ExecuteNonQueryAsync(ct)!=1)continue;await using(var q=new NpgsqlCommand("UPDATE kfzb_matches SET state=2,winner_player_id=$2,resolved_at=now() WHERE id=$1;INSERT INTO kfzb_rewards(season_id,player_id,wins,losses) VALUES($3,$2,1,0),($3,$4,0,1) ON CONFLICT(season_id,player_id) DO UPDATE SET wins=kfzb_rewards.wins+excluded.wins,losses=kfzb_rewards.losses+excluded.losses,updated_at=now()",c,t)){q.Parameters.AddWithValue(x.id);q.Parameters.AddWithValue(x.winner);q.Parameters.AddWithValue(x.season);q.Parameters.AddWithValue(x.winner==x.p1?x.p2:x.p1);await q.ExecuteNonQueryAsync(ct);}await using(var support=new NpgsqlCommand("UPDATE kfzb_supports s SET rewarded=CASE WHEN s.target_competitor_id=(SELECT competitor_id FROM kfzb_signups WHERE season_id=$2 AND player_id=$3) THEN 1 ELSE -1 END WHERE s.match_id=$1 AND s.rewarded=0",c,t)){support.Parameters.AddWithValue(x.id);support.Parameters.AddWithValue(x.season);support.Parameters.AddWithValue(x.winner);await support.ExecuteNonQueryAsync(ct);}if(x.phase==2){var loser=x.winner==x.p1?x.p2:x.p1;var title=x.layer<=4?KfzbTitle(x.layer):null;await using var q=new NpgsqlCommand("UPDATE kfzb_signups SET eliminated=true WHERE season_id=$1 AND player_id=$2;UPDATE kfzb_rewards SET eliminated_layer=$3,title=$4,updated_at=now() WHERE season_id=$1 AND player_id=$2",c,t);q.Parameters.AddWithValue(x.season);q.Parameters.AddWithValue(loser);q.Parameters.AddWithValue(x.layer);q.Parameters.AddWithValue("title",NpgsqlTypes.NpgsqlDbType.Text,(object?)title??DBNull.Value);await q.ExecuteNonQueryAsync(ct);if(x.layer==1){await using var champion=new NpgsqlCommand("UPDATE kfzb_rewards SET eliminated_layer=0,title=$3,updated_at=now() WHERE season_id=$1 AND player_id=$2",c,t);champion.Parameters.AddWithValue(x.season);champion.Parameters.AddWithValue(x.winner);champion.Parameters.AddWithValue(KfzbTitle(0));await champion.ExecuteNonQueryAsync(ct);}}}await t.CommitAsync(ct);foreach(var x in done){await push.SendAsync(x.p1,"kfzb.result",new{matchId=x.id,winner=x.winner},ct);await push.SendAsync(x.p2,"kfzb.result",new{matchId=x.id,winner=x.winner},ct);}}
 static string KfzbTitle(int layer)=>layer switch{0=>"天下第一擂主",1=>"天下第二擂主",2=>"四强擂主",3=>"八强擂主",4=>"海选擂主",_=>throw new GameException("KFZB_LAYER_INVALID","Legacy KFZB title layer is invalid.",500)};
 async Task<KfzbView> ReadAsync(NpgsqlConnection c,long player,CancellationToken ct){await using var q=new NpgsqlCommand("SELECT s.id,s.season_no,s.global_state,CASE WHEN s.global_state=10 THEN s.signup_opens_at WHEN s.global_state=20 THEN s.qualifier_opens_at WHEN s.global_state<51 THEN s.phase2_opens_at ELSE s.ends_at END,s.min_level,s.support_level,p.level,g.competitor_id,g.general_ids,g.eliminated,r.wins,r.losses FROM kfzb_seasons s JOIN players p ON p.id=$1 LEFT JOIN kfzb_signups g ON g.season_id=s.id AND g.player_id=p.id LEFT JOIN kfzb_rewards r ON r.season_id=s.id AND r.player_id=p.id ORDER BY s.season_no DESC LIMIT 1",c);q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("KFZB_INACTIVE","No KFZB season is available.",404);var season=r.GetInt64(0);var signed=!r.IsDBNull(7);var v=new KfzbView(season,r.GetInt32(1),r.GetInt16(2),r.GetFieldValue<DateTimeOffset>(3),r.GetInt32(4),r.GetInt32(5),r.GetInt32(6)>=r.GetInt32(4),signed,signed&&!r.IsDBNull(8),signed&&r.GetBoolean(9),signed?r.GetInt64(7):null,r.IsDBNull(10)?0:r.GetInt32(10),r.IsDBNull(11)?0:r.GetInt32(11),null);await r.CloseAsync();await using var m=new NpgsqlCommand("SELECT id,phase,layer_no,round_no,legacy_match_id,CASE WHEN player1_id=$2 THEN player2_id ELSE player1_id END,battle_id,state,winner_player_id,starts_at,deadline_at FROM kfzb_matches WHERE season_id=$1 AND (player1_id=$2 OR player2_id=$2) ORDER BY phase DESC,layer_no DESC,round_no DESC LIMIT 1",c);m.Parameters.AddWithValue(season);m.Parameters.AddWithValue(player);await using var mr=await m.ExecuteReaderAsync(ct);if(await mr.ReadAsync(ct))v=v with{Match=new(mr.GetInt64(0),mr.GetInt16(1),mr.GetInt32(2),mr.GetInt32(3),mr.GetInt32(4),mr.GetInt64(5),mr.IsDBNull(6)?null:mr.GetInt64(6),mr.GetInt16(7),mr.IsDBNull(8)?null:mr.GetInt64(8),mr.GetFieldValue<DateTimeOffset>(9),mr.GetFieldValue<DateTimeOffset>(10))};return v;}
}
public sealed class KfzbWorker(KfzbService service,GameDb db,GamePushHub push,ISystemMailSender mail,ILogger<KfzbWorker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){using var timer=new PeriodicTimer(TimeSpan.FromSeconds(10));while(await timer.WaitForNextTickAsync(ct))try{await service.TickAsync(ct);await KfzbRewardLifecycle.MaintainAsync(db,push,mail,ct);}catch(Exception e){log.LogError(e,"KFZB scheduler tick failed");}}}
